/// <summary>
/// 单房间管理器 — 管理单个房间的运行时状态。
/// 负责怪物生成、门锁定/解锁、道具生成等。
/// </summary>
public class RoomManager : MonoBehaviour
{
    [Header("组件引用")]
    public RoomRoot roomRoot;

    [Header("货币掉落")]
    [SerializeField] private int _currencyPerEnemy = 3;
    [SerializeField] private Sprite _currencyIcon;

    [Header("房间状态")]
    [SerializeField] private bool _isCleared;
    private bool _isFirstEnter = true;

    /// <summary>房间是否已清完怪物</summary>
    public bool IsCleared => _isCleared;

    /// <summary>是否首次进入</summary>
    public bool IsFirstEnter => _isFirstEnter;

    /// <summary>当前存活怪物列表</summary>
    private List<GameObject> _aliveEnemies = new();

    /// <summary>所有门 Portal 引用</summary>
    private List<RoomPortal> _portals = new();

    public event System.Action OnRoomCleared;

    private void Awake()
    {
        if (roomRoot == null)
            roomRoot = GetComponent<RoomRoot>();

        // 自动加载货币图标
        if (_currencyIcon == null)
            _currencyIcon = Resources.Load<Sprite>("TestAssets/Icons/icon_atp");

        _portals.AddRange(GetComponentsInChildren<RoomPortal>());

        // 确保每次实例化都是首次进入状态 (防止序列化残留)
        _isFirstEnter = true;
        _isCleared = roomRoot.config.maxEnemies == 0? true : false;
    }

    /// <summary>玩家进入房间时调用</summary>
    public void OnPlayerEnter()
    {
        if (roomRoot == null) roomRoot = GetComponent<RoomRoot>();
        if (roomRoot == null || roomRoot.config == null) return;

        // Shop 房间特殊处理：开张商店
        if (roomRoot.config.roomType == RoomType.Shop)
        {
            if (_isFirstEnter)
            {
                _isFirstEnter = false;
                OpenShopRoom();
            }
            return;
        }

        Debug.Log($"[RoomManager] Room{roomRoot.roomId} OnPlayerEnter: _isFirstEnter={_isFirstEnter}, enemyPool={roomRoot.config.enemyPool?.Count}, minEnemies={roomRoot.config.minEnemies}");

        if (_isFirstEnter)
        {
            _isFirstEnter = false;

            // 统计：首次进入房间
            GameStatistics.Instance?.RecordRoomVisited(roomRoot.config.roomType);

            SpawnEnemies();
            Debug.Log($"[RoomManager] Room{roomRoot.roomId} spawned enemies, _aliveEnemies.Count={_aliveEnemies.Count}");

            if (_aliveEnemies.Count > 0)
            {
                Debug.Log($"[RoomManager] Room{roomRoot.roomId} calling LockDoors...");
                LockDoors();
                Debug.Log($"[RoomManager] Room{roomRoot.roomId} LockDoors done.");
            }
        }
    }

    /// <summary>玩家离开房间时调用</summary>
    public void OnPlayerExit()
    {
        // 道具现在是普通 ItemPickup，离开后保留在地图中
    }

    /// <summary>锁定所有门 (启用阻挡物 + 禁用触发器)</summary>
    private void LockDoors()
    {
        foreach (var portal in _portals)
        {
            if (portal != null)
                portal.SetLocked(true);
        }
    }

    /// <summary>解锁所有门 (启用触发器 + 禁用阻挡物)，跳过隐藏墙</summary>
    private void UnlockDoors()
    {
        foreach (var portal in _portals)
        {
            if (portal != null && portal.HiddenWallHP <= 0)
                portal.SetLocked(false);
        }
    }

    /// <summary>生成怪物</summary>
    private void SpawnEnemies()
    {
        if (roomRoot == null || roomRoot.config == null) return;

        var cfg = roomRoot.config;
        if (cfg.enemyPool == null || cfg.enemyPool.Count == 0) return;

        // 按权重选择敌人
        int totalEnemies = Random.Range(cfg.minEnemies, cfg.maxEnemies + 1);
        int spawnPointCount = roomRoot.enemySpawnPoints != null ? roomRoot.enemySpawnPoints.Length : 0;

        if (spawnPointCount == 0)
        {
            Debug.LogWarning($"Room {roomRoot.roomId}: 没有敌人生成点");
            return;
        }

        // 随机选取生成点 (不重复)
        var availablePoints = new List<int>();
        for (int i = 0; i < spawnPointCount; i++)
            availablePoints.Add(i);
        Shuffle(availablePoints);

        int spawnCount = Mathf.Min(totalEnemies, availablePoints.Count);

        for (int i = 0; i < spawnCount; i++)
        {
            // 按权重随机选择敌人类型
            var entry = PickWeighted(cfg.enemyPool);
            if (entry == null || entry.enemyPrefab == null) continue;

            var spawnPoint = roomRoot.enemySpawnPoints[availablePoints[i]];
            var enemy = Instantiate(entry.enemyPrefab, spawnPoint.position, Quaternion.identity, transform);
            _aliveEnemies.Add(enemy);

            // 监听敌人死亡，使用 IEnemy 接口
            if (enemy.TryGetComponent<IEnemy>(out var ienemy))
            {
                ienemy.OnDied += () => OnEnemyDied(enemy);
                ienemy.OnAssimilated += (_) => OnEnemyAssimilated(enemy);
            }
        }

        Debug.Log($"Room {roomRoot.roomId}: 生成了 {spawnCount} 个敌人");
    }

    /// <summary>按权重随机选择</summary>
    private EnemySpawnEntry PickWeighted(List<EnemySpawnEntry> entries)
    {
        float totalWeight = 0f;
        foreach (var e in entries) totalWeight += e.weight;

        if (totalWeight <= 0f) return entries.Count > 0 ? entries[0] : null;

        float roll = Random.Range(0f, totalWeight);
        float cumulative = 0f;
        foreach (var e in entries)
        {
            cumulative += e.weight;
            if (roll <= cumulative)
                return e;
        }
        return entries[^1];
    }

    /// <summary>敌人死亡回调</summary>
    private void OnEnemyDied(GameObject enemy)
    {
        _aliveEnemies.Remove(enemy);

        // 生成货币掉落
        SpawnCurrency(enemy.transform.position, _currencyPerEnemy);

        if (_aliveEnemies.Count == 0)
        {
            OnAllEnemiesDefeated();
        }
    }

    /// <summary>敌人被同化为随从（不再计入房间清空判定）</summary>
    private void OnEnemyAssimilated(GameObject enemy)
    {
        _aliveEnemies.Remove(enemy);

        if (_aliveEnemies.Count == 0)
        {
            OnAllEnemiesDefeated();
        }
    }

    /// <summary>所有敌人被击败</summary>
    private void OnAllEnemiesDefeated()
    {
        _isCleared = true;

        // 解锁门
        UnlockDoors();

        // 激活相邻隐藏房的门 (变为可破坏状态)
        ActivateHiddenWalls();

        // 生成道具奖励
        SpawnItems();

        // Boss/Exit 房生成下一层出口
        TrySpawnNextLevelExit();

        Debug.Log($"Room {roomRoot.roomId}: 已清空!");

        // 统计：清空房间
        GameStatistics.Instance?.RecordRoomCleared(roomRoot.config.roomType);

        OnRoomCleared?.Invoke();
    }

    /// <summary>Boss/Exit 房清空后在房间中心生成下一层出口</summary>
    private void TrySpawnNextLevelExit()
    {
        if (roomRoot == null || roomRoot.config == null) return;
        var roomType = roomRoot.config.roomType;
        if (roomType != RoomType.Boss && roomType != RoomType.Exit) return;

        var mapConfigAsset = MapManager.Instance?.MapConfigAsset;
        if (mapConfigAsset == null) return;

        var exitGo = Instantiate(mapConfigAsset.nextLevelExitPrefab, roomRoot.Center, Quaternion.identity, transform);
        exitGo.name = "NextLevelExit";

        var exitComp = exitGo.GetComponent<NextLevelExit>();
        if (exitComp == null)
        {
            Debug.LogError("RoomManager: nextLevelExitPrefab 上没有挂载 NextLevelExit 组件，请在预制体上添加该脚本");
            return;
        }
        exitComp.nextSceneName = mapConfigAsset.nextSceneName;

        Debug.Log($"RoomManager: 房间 {roomRoot.roomId} 生成下一层出口 -> {mapConfigAsset.nextSceneName}");
    }

    /// <summary>激活通往相邻隐藏房的门</summary>
    private void ActivateHiddenWalls()
    {
        if (roomRoot == null) return;
        var graph = MapManager.Instance?.RoomGraph;
        if (graph == null) return;

        var node = graph.GetNode(roomRoot.roomId);
        if (node == null) return;

        foreach (var conn in node.connections)
        {
            var targetNode = graph.GetNode(conn.Key);
            if (targetNode == null || targetNode.roomType != RoomType.Hidden) continue;

            // 找到指向隐藏房的门 Portal
            var portals = GetComponentsInChildren<RoomPortal>(true);
            foreach (var portal in portals)
            {
                if (portal.targetRoomId == conn.Key && portal.HiddenWallHP > 0)
                {
                    portal.SetBreakable();
                    break;
                }
            }
        }
    }

    /// <summary>生成道具</summary>
    private void SpawnItems()
    {
        if (roomRoot == null || roomRoot.config == null) return;
        var cfg = roomRoot.config;
        if (cfg.itemPool == null || cfg.itemPool.Count == 0) return;

        int totalItems = Random.Range(cfg.minItems, cfg.maxItems + 1);
        int spawnPointCount = roomRoot.itemSpawnPoints != null ? roomRoot.itemSpawnPoints.Length : 0;
        if (spawnPointCount == 0) return;

        int spawnCount = Mathf.Min(totalItems, spawnPointCount);

        for (int i = 0; i < spawnCount; i++)
        {
            int idx = Random.Range(0, cfg.itemPool.Count);
            var itemPrefab = cfg.itemPool[idx];
            if (itemPrefab == null) continue;

            Instantiate(itemPrefab, roomRoot.itemSpawnPoints[i].position, Quaternion.identity, transform);
        }
    }

    /// <summary>协程: 轮询检查敌人死亡 (用于未继承 BaseEnemy 的敌人)</summary>
    private System.Collections.IEnumerator WatchEnemyDeath(GameObject enemy)
    {
        while (enemy != null)
        {
            yield return new WaitForSeconds(0.5f);
        }
        OnEnemyDied(null);
    }

    private static void Shuffle<T>(List<T> list)
    {
        for (int i = list.Count - 1; i > 0; i--)
        {
            int j = Random.Range(0, i + 1);
            (list[i], list[j]) = (list[j], list[i]);
        }
    }

    // ==================== Shop 房间 ====================

    /// <summary>开张商店</summary>
    private void OpenShopRoom()
    {
        var shopManager = GetComponent<ShopManager>();
        if (shopManager == null)
        {
            Debug.LogWarning($"[RoomManager] Room{roomRoot.roomId}: Shop 房间但未挂载 ShopManager 组件");
            return;
        }

        shopManager.OpenShop();
    }

    /// <summary>打烊商店</summary>
    private void CloseShopRoom()
    {
        var shopManager = GetComponent<ShopManager>();
        if (shopManager != null)
            shopManager.CloseShop();
    }

    /// <summary>在指定位置生成货币掉落物</summary>
    private void SpawnCurrency(Vector3 position, int amount)
    {
        var go = new GameObject("CurrencyPickup", typeof(SpriteRenderer), typeof(CircleCollider2D), typeof(CurrencyPickup));

        var sr = go.GetComponent<SpriteRenderer>();
        sr.sprite = _currencyIcon;
        sr.sortingOrder = 5;

        var col = go.GetComponent<CircleCollider2D>();
        col.isTrigger = true;
        col.radius = 0.4f;

        var pickup = go.GetComponent<CurrencyPickup>();
        pickup.amount = amount;

        // 随机散布
        position += (Vector3)(Random.insideUnitCircle * 0.5f);
        go.transform.position = position;
        go.transform.SetParent(transform);
    }
}

using UnityEngine;

/// <summary>
/// 房间门 — 挂载在每个门 GO 上。
/// 普通门：Trigger 检测玩家 → 切换房间。
/// 隐藏墙：清房后 openTrigger 启用但不放行玩家，子弹命中 N 次后墙壁破碎，显示门。
/// 无连接的门：直接隐藏，不出现墙壁贴图。
/// </summary>
public class RoomPortal : MonoBehaviour
{
    [Header("门配置")]
    public DoorDirection direction;
    public int targetRoomId = -1;

    [Header("组件引用")]
    [Tooltip("门 GO 的 SpriteRenderer")]
    public SpriteRenderer doorSprite;

    [Tooltip("开门/子弹检测的 Trigger Collider")]
    public Collider2D openTrigger;

    [Tooltip("关门/隐藏墙时激活的阻挡物")]
    public GameObject doorBlocker;

    [Header("触发设置")]
    public string targetTag = "Player";

    private bool _locked;
    private bool _hidden;       // 无连接，永久隐藏
    private bool _breakable;
    private int _hiddenWallHP;
    private int _currentHP;

    private void Awake()
    {
        if (doorSprite == null) doorSprite = GetComponent<SpriteRenderer>();
        if (openTrigger == null) openTrigger = GetComponent<Collider2D>();
        if (openTrigger != null) openTrigger.isTrigger = true;
    }

    private void OnTriggerEnter2D(Collider2D other)
    {
        // 可破坏墙壁：检测子弹
        if (_breakable && other.TryGetComponent<Projectile>(out var proj))
        {
            OnBulletHit(proj);
            return;
        }

        // 隐藏墙未破坏前不放行玩家 (_locked 为 true)
        if (_locked) return;

        // 正常的门传送
        if (targetRoomId < 0) return;
        if (!other.CompareTag(targetTag)) return;
        if (MapManager.Instance == null) return;
        if (other.GetComponent<PlayerStats>() == null) return;

        MapManager.Instance.SwitchRoom(targetRoomId, direction);
    }

    private void OnBulletHit(Projectile proj)
    {
        _currentHP--;
        Destroy(proj.gameObject);

        if (_currentHP <= 0)
            BreakWall();
    }

    private void BreakWall()
    {
        _breakable = false;
        _hiddenWallHP = 0;
        _locked = false;

        // 隐藏墙破坏后显示门
        if (doorBlocker != null) doorBlocker.SetActive(false);
        if (doorSprite != null) doorSprite.enabled = true;
        if (openTrigger != null) openTrigger.enabled = true;

        Debug.Log($"RoomPortal: 隐藏墙已破坏, 门已显示 (方向: {direction})");
    }

    /// <summary>设置为隐藏墙</summary>
    public void SetAsBreakableWall(int hp)
    {
        if (hp <= 0) return;
        _hiddenWallHP = hp;
        _currentHP = hp;
        _breakable = false;
        _locked = true;

        if (doorSprite != null) doorSprite.enabled = false;
        if (openTrigger != null) openTrigger.enabled = false;
        if (doorBlocker != null) doorBlocker.SetActive(true);
    }

    /// <summary>激活可破坏状态（清房后调用）：启用 openTrigger 接收子弹</summary>
    public void SetBreakable()
    {
        if (_hiddenWallHP <= 0 || _breakable) return;
        _breakable = true;
        if (openTrigger != null) openTrigger.enabled = true;
        Debug.Log($"RoomPortal: 隐藏墙可破坏 (方向: {direction}, HP: {_currentHP})");
    }

    public bool IsBreakable => _breakable;
    public int HiddenWallHP => _hiddenWallHP;

    /// <summary>锁定/解锁门</summary>
    public void SetLocked(bool locked)
    {
        if (_hidden) return;
        _locked = locked;

        if (openTrigger != null)
            openTrigger.enabled = !locked;

        if (doorSprite != null)
            doorSprite.enabled = !locked;

        if (doorBlocker != null)
            doorBlocker.SetActive(locked);
    }

    /// <summary>永久隐藏门（无连接房间），不显示墙壁贴图</summary>
    public void HideAsWall()
    {
        targetRoomId = -1;
        _hidden = true;
        _breakable = false;
        _hiddenWallHP = 0;

        if (openTrigger != null) openTrigger.enabled = false;
        if (doorSprite != null) doorSprite.enabled = false;
        if (doorBlocker != null) doorBlocker.SetActive(false);
    }
}

using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// 房间根节点 — 挂载在每个房间预制体的根 GameObject 上。
/// 管理房间的激活/隐藏、门位置查询、生成点等。
/// </summary>
public class RoomRoot : MonoBehaviour
{
    [Header("房间配置")]
    public RoomConfig config;

    [Header("房间 ID (运行时赋值)")]
    public int roomId;

    [Header("门 Transform (按方向索引: Top=0, Bottom=1, Left=2, Right=3)")]
    public Transform topDoor;
    public Transform bottomDoor;
    public Transform leftDoor;
    public Transform rightDoor;

    [Header("敌人生成点")]
    public Transform[] enemySpawnPoints;

    [Header("道具生成点")]
    public Transform[] itemSpawnPoints;

    [Header("房间边界 (用于摄像机)")]
    public Vector2 roomSize = new Vector2(20f, 12f);

    /// <summary>获取房间中心世界坐标</summary>
    public Vector2 Center => (Vector2)transform.position;

    /// <summary>获取房间边界矩形</summary>
    public Rect Bounds => new(Center - roomSize * 0.5f, roomSize);

    /// <summary>获取指定方向门的世界坐标</summary>
    public Vector3 GetDoorWorldPosition(DoorDirection dir)
    {
        var t = GetDoorTransform(dir);
        return t != null ? t.position : transform.position;
    }

    /// <summary>获取指定方向门的 Transform</summary>
    public Transform GetDoorTransform(DoorDirection dir)
    {
        return dir switch
        {
            DoorDirection.Top => topDoor,
            DoorDirection.Bottom => bottomDoor,
            DoorDirection.Left => leftDoor,
            DoorDirection.Right => rightDoor,
            _ => null
        };
    }

    /// <summary>获取所有可用的门方向</summary>
    public List<DoorDirection> GetAvailableDoors()
    {
        var doors = new List<DoorDirection>();
        if (topDoor != null) doors.Add(DoorDirection.Top);
        if (bottomDoor != null) doors.Add(DoorDirection.Bottom);
        if (leftDoor != null) doors.Add(DoorDirection.Left);
        if (rightDoor != null) doors.Add(DoorDirection.Right);
        return doors;
    }

    private List<GameObject> _childrenCache = new();

    /// <summary>激活房间 (显示所有子物体)</summary>
    public void Activate()
    {
        gameObject.SetActive(true);
    }

    /// <summary>隐藏房间</summary>
    public void Deactivate()
    {
        gameObject.SetActive(false);
    }

    private void OnDrawGizmosSelected()
    {
        Gizmos.color = Color.green;
        Gizmos.DrawWireCube(Center, roomSize);

        if (config != null)
        {
            var dirs = new[] { DoorDirection.Top, DoorDirection.Bottom, DoorDirection.Left, DoorDirection.Right };
            foreach (var dir in dirs)
            {
                if (config.HasDoor(dir))
                {
                    Gizmos.color = Color.yellow;
                    Gizmos.DrawSphere(GetDoorWorldPosition(dir), 0.3f);
                }
            }
        }
    }
}

using UnityEngine;

/// <summary>
/// 怪物生成器 — 可独立使用或挂载在房间上
/// 负责从配置中读取怪物池并按权重生成敌人
/// </summary>
public class EnemySpawner : MonoBehaviour
{
    [Header("生成配置")]
    [Tooltip("引用房间配置 (为空则使用下方手动配置)")]
    public RoomConfig roomConfig;

    [Tooltip("手动配置 — 仅在没有 roomConfig 时使用")]
    public EnemySpawnEntry[] manualEntries;
    public int manualMinEnemies = 1;
    public int manualMaxEnemies = 3;

    [Header("生成点")]
    public Transform[] spawnPoints;

    /// <summary>存活怪物追踪</summary>
    public event System.Action OnAllEnemiesDefeated;

    private int _aliveCount;
    private bool _hasSpawned;

    /// <summary>开始生成</summary>
    public void Spawn()
    {
        if (_hasSpawned) return;
        _hasSpawned = true;

        var entries = roomConfig != null ? roomConfig.enemyPool : 
            (manualEntries != null ? new System.Collections.Generic.List<EnemySpawnEntry>(manualEntries) : null);

        if (entries == null || entries.Count == 0) return;

        int min = roomConfig != null ? roomConfig.minEnemies : manualMinEnemies;
        int max = roomConfig != null ? roomConfig.maxEnemies : manualMaxEnemies;
        int total = Random.Range(min, max + 1);
        int available = spawnPoints != null ? spawnPoints.Length : 0;
        if (available == 0) return;

        int count = Mathf.Min(total, available);

        // 洗牌生成点
        var indices = new int[available];
        for (int i = 0; i < available; i++) indices[i] = i;
        for (int i = indices.Length - 1; i > 0; i--)
        {
            int j = Random.Range(0, i + 1);
            (indices[i], indices[j]) = (indices[j], indices[i]);
        }

        for (int i = 0; i < count; i++)
        {
            var entry = PickWeighted(entries);
            if (entry == null || entry.enemyPrefab == null) continue;

            var point = spawnPoints[indices[i]];
            var enemy = Instantiate(entry.enemyPrefab, point.position, Quaternion.identity, transform);

            _aliveCount++;

            // 监听死亡和同化（使用 IEnemy 接口以便兼容重构后的敌人）
            if (enemy.TryGetComponent<IEnemy>(out var ienemy))
            {
                ienemy.OnDied += () =>
                {
                    _aliveCount--;
                    if (_aliveCount <= 0)
                        OnAllEnemiesDefeated?.Invoke();
                };
                ienemy.OnAssimilated += (_) =>
                {
                    _aliveCount--;
                    if (_aliveCount <= 0)
                        OnAllEnemiesDefeated?.Invoke();
                };
            }
        }
    }

    private EnemySpawnEntry PickWeighted(System.Collections.Generic.List<EnemySpawnEntry> entries)
    {
        float total = 0f;
        foreach (var e in entries) total += e.weight;
        if (total <= 0f) return entries[0];

        float roll = Random.Range(0f, total);
        float cumulative = 0f;
        foreach (var e in entries)
        {
            cumulative += e.weight;
            if (roll <= cumulative) return e;
        }
        return entries[^1];
    }
}

using UnityEngine;

/// <summary>
/// 道具生成器 — 从道具池中随机生成道具
/// </summary>
public class ItemSpawner : MonoBehaviour
{
    [Header("道具池")]
    [Tooltip("引用房间配置")]
    public RoomConfig roomConfig;

    [Tooltip("手动配置 — 仅在没有 roomConfig 时使用")]
    public GameObject[] manualItemPool;
    public int manualMinItems = 1;
    public int manualMaxItems = 3;

    [Header("生成点")]
    public Transform[] spawnPoints;

    private bool _hasSpawned;

    /// <summary>生成道具</summary>
    public void Spawn()
    {
        if (_hasSpawned) return;
        _hasSpawned = true;

        var pool = roomConfig != null ? roomConfig.itemPool : 
            (manualItemPool != null ? new System.Collections.Generic.List<GameObject>(manualItemPool) : null);

        if (pool == null || pool.Count == 0) return;

        // 过滤：玩家已达拾取上限的道具不再刷新
        pool = ItemPoolFilter.GetAvailablePool(pool, ItemPoolFilter.GetPlayerItemManager());
        if (pool == null || pool.Count == 0)
        {
            Debug.Log("[ItemSpawner] 道具池中所有道具均已达上限，跳过生成");
            return;
        }

        int min = roomConfig != null ? roomConfig.minItems : manualMinItems;
        int max = roomConfig != null ? roomConfig.maxItems : manualMaxItems;
        int total = Random.Range(min, max + 1);
        int available = spawnPoints != null ? spawnPoints.Length : 0;

        if (available == 0) return;

        int count = Mathf.Min(total, available);

        // 随机洗牌但不重复点
        var indices = new int[available];
        for (int i = 0; i < available; i++) indices[i] = i;
        for (int i = indices.Length - 1; i > 0; i--)
        {
            int j = Random.Range(0, i + 1);
            (indices[i], indices[j]) = (indices[j], indices[i]);
        }

        for (int i = 0; i < count; i++)
        {
            int idx = Random.Range(0, pool.Count);
            var itemPrefab = pool[idx];
            if (itemPrefab == null) continue;

            Instantiate(itemPrefab, spawnPoints[indices[i]].position, Quaternion.identity, transform);
        }
    }
}

